package com.phoenix.business.repository;import com.phoenix.business.domain.Member;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import org.springframework.data.domain.*;import java.time.LocalDate;import java.util.List;public interface MemberRepository extends JpaRepository<Member,Long>{@Query("select m from Member m left join fetch m.plan where m.archived=:archived and (:q is null or lower(m.name) like lower(concat('%',:q,'%')) or lower(m.memberCode) like lower(concat('%',:q,'%')) or lower(coalesce(m.phone,'')) like lower(concat('%',:q,'%'))) and (:status is null or m.status=:status)")Page<Member> search(@Param("q")String q,@Param("status")Member.Status status,@Param("archived")boolean archived,Pageable pageable);default Page<Member> search(String q,Member.Status status,Pageable p){return search(q,status,false,p);}@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @Query("select m from Member m where m.id=:id") java.util.Optional<Member> findLockedById(@Param("id")Long id);long countByArchivedFalse();@Modifying @Query("update Member m set m.status=com.phoenix.business.domain.Member.Status.EXPIRED where m.archived=false and m.status=com.phoenix.business.domain.Member.Status.ACTIVE and m.expiryDate<:today") int expireBefore(@Param("today")LocalDate today);long countByArchivedFalseAndStatus(Member.Status s);long countByArchivedFalseAndStatusAndExpiryDateBetween(Member.Status s,LocalDate a,LocalDate b);long countByJoinDateBetween(LocalDate a,LocalDate b);boolean existsByEmailIgnoreCaseAndIdNot(String email,Long id);boolean existsByPhoneAndIdNot(String phone,Long id);List<Member> findByArchivedFalseAndExpiryDateBetween(LocalDate from,LocalDate to);@Query("select coalesce(m.plan.name,'No plan'),count(m) from Member m where m.archived=false group by m.plan.name")List<Object[]> membershipDistribution();}
